import React, { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import DocTab from '../DocTab';
import { getDocPageWrapperMetaPath, getFolderNameFromLowercase } from '../../../Constants/docs/folderMapping';

/**
 * Common wrapper component for all documentation pages
 * Handles dynamic meta loading and DocTab rendering
 * 
 * @param {string} componentName - The component name for the key prop (e.g., "button", "iconfield")
 * @param {string} metaPath - Optional custom path to the meta file (auto-generated if not provided)
 */
export default function DocPageWrapper({ componentName, metaPath }) {
  const [meta, setMeta] = useState(null);
  const location = useLocation();
  
  useEffect(() => {
    const loadMeta = async () => {
      try {
        // Check for custom demo meta first, then fall back to master
        const folderName = getFolderNameFromLowercase(componentName);
        const customDemoMetaPath = `/src/custom-demo/${folderName}/meta`;
        const masterMetaPath = metaPath || getDocPageWrapperMetaPath(componentName);
        
        let module;
        try {
          // Try custom demo meta first
          console.log(`🔍 Attempting to load custom demo meta from: ${customDemoMetaPath}`);
          module = await import(/* @vite-ignore */ customDemoMetaPath);
          console.log(`✅ Using custom demo meta for ${componentName}`);
        } catch (customError) {
          // Fall back to master meta
          console.log(`⚠️  Custom demo meta not found, falling back to master: ${masterMetaPath}`);
          console.log(`   Error: ${customError.message}`);
          module = await import(/* @vite-ignore */ masterMetaPath);
        }
        
        setMeta(module.default);
      } catch (error) {
        console.error(`Failed to load meta for ${componentName}:`, error);
        setMeta(null); // Handle error state
      }
    };
    loadMeta();
  }, [location.pathname, componentName, metaPath]);
  
  if (!meta) {
    return <div>Loading...</div>;
  }
  
  return <DocTab key={componentName} meta={meta} />;
}
